#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <string.h>

int main() {
    // ファイルのオープン
    int fd = open("testfile", O_RDWR | O_CREAT, 0644);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // ファイルのマッピング
    struct stat sb;
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        exit(EXIT_FAILURE);
